include { GFFCOMPARE                      } from 'nf-core/gffcompare'
include { GAWK as GAWK_FILTER             } from 'nf-core/gawk'
include { BEDTOOLS_INTERSECT              } from 'nf-core/bedtools/intersect'
include { GAWK as GAWK_CONCAT             } from 'nf-core/gawk'

workflow GTF_HYBRIDMERGE_GFFCOMPARE {

    take:
    ch_novel_gtf         // channel: [ val(meta), path(novel_gtf) ]
    ch_reference_gtf     // channel: [ val(meta), path(reference_gtf) ]
    ch_backbone_gtf      // channel: [ val(meta), path(backbone_gtf) ]
    val_class_codes      // channel: val (String or List of gffcompare class codes to keep, e.g. "u" or "u,j,i")
    ch_blacklist_bed     // channel: [ val(meta), path(blacklist_bed) ] or channel.empty() to skip the intersect

    main:

    // Bundled awk programs (see ./awk/{filter,concat}.awk); shipped alongside
    // the subworkflow and passed to GAWK as `program_file` so the awk source
    // stays readable as awk rather than as an escaped Groovy string.
    ch_filter_awk = file("${moduleDir}/awk/filter.awk", checkIfExists: true)
    ch_concat_awk = file("${moduleDir}/awk/concat.awk", checkIfExists: true)

    // Tag every novel transcript with a gffcompare class_code attribute.
    GFFCOMPARE(
        ch_novel_gtf,
        [[:], [], []],
        ch_reference_gtf
    )

    // Fold class codes onto meta so GAWK_FILTER's ext.args closure can read them at task launch.
    ch_filter_input = GFFCOMPARE.out.annotated_gtf
        .combine(val_class_codes)
        .map { meta, gtf, codes ->
            def codes_csv = codes instanceof List ? codes.join(',') : "${codes}"
            [ meta + [class_codes: codes_csv], gtf, "gtf" ]
        }

    // Drop transcripts whose class_code is not in the caller-supplied set.
    GAWK_FILTER(ch_filter_input, ch_filter_awk, false)

    // Branch: send survivors through BEDTOOLS_INTERSECT only when a blacklist BED was supplied.
    // Bedtools args (-v for negation, -s for strand) are caller policy in modules.config.
    ch_after_filter = GAWK_FILTER.out.output
        .combine(ch_blacklist_bed.ifEmpty([[:], []]))
        .branch { _meta, _gtf, _bed_meta, bed ->
            with_blacklist: bed
            passthrough:    !bed
        }

    BEDTOOLS_INTERSECT(
        ch_after_filter.with_blacklist.map { meta, gtf, _bed_meta, bed -> [ meta, gtf, bed ] },
        [[:], []],
        ''
    )

    ch_post_blacklist = BEDTOOLS_INTERSECT.out.intersect
        .mix(ch_after_filter.passthrough.map { meta, gtf, _bed_meta, _bed -> [ meta, gtf ] })

    // Adopt the backbone's meta (the hybrid identity follows the backbone) and stage
    // [backbone, novel] in that order so backbone gene rows reach the concat awk first.
    ch_concat_input = ch_post_blacklist
        .combine(ch_backbone_gtf)
        .map { _novel_meta, novel_gtf, backbone_meta, backbone_gtf ->
            [ backbone_meta, [ backbone_gtf, novel_gtf ], "gtf" ]
        }

    // Concatenate and synthesise missing gene rows with union spans.
    GAWK_CONCAT(ch_concat_input, ch_concat_awk, false)

    emit:
    hybrid_gtf          = GAWK_CONCAT.out.output       // channel: [ val(meta), path(hybrid.gtf) ]
    gffcompare_stats    = GFFCOMPARE.out.stats         // channel: [ val(meta), path(stats) ]
    gffcompare_tracking = GFFCOMPARE.out.tracking      // channel: [ val(meta), path(tracking) ]
    gffcompare_loci     = GFFCOMPARE.out.loci          // channel: [ val(meta), path(loci) ]
}

/*
 * IMPORTANT: This config file should be included by consumer pipelines (via
 * `includeConfig`) or passed with `-c` for standalone runs; it carries the
 * meta / args / prefix settings that GAWK_FILTER, GAWK_CONCAT and
 * BEDTOOLS_INTERSECT need. The awk programs themselves live as proper
 * `.awk` files in `awk/` next to the subworkflow main.nf and are passed
 * through as `program_file` from there.
 *
 * Resource sizing: GAWK steps hold the full input in memory under
 * `process_single`. Fine for annotation-scale GTFs; for >~500 MB inputs
 * override `memory` / `cpus` directly via `withName`.
 *
 * Annotation format: the bundled awks assume standard GTF2 with `gene_id`
 * and `transcript_id` attributes in column 9 and `gene` / `transcript` in
 * column 3. GFF3 inputs (Parent= / ID= attributes), prokaryotic GTFs
 * without transcript rows, and any other dialect are out of scope.
 */
process {

    // GAWK_FILTER (awk/filter.awk): keeps the records belonging to
    // transcripts whose gffcompare class_code is in the caller-supplied set
    // passed through `meta.class_codes`.
    withName: '.*GTF_HYBRIDMERGE_GFFCOMPARE:GAWK_FILTER' {
        ext.args   = { "-v codes_csv='${meta.class_codes}'" }
        ext.prefix = { "${meta.id}_filtered" }
    }

    // BEDTOOLS_INTERSECT: `-v` makes "blacklist" mean subtraction. Consumers
    // can override (`-v -s`, positive overlap, etc.) in their modules.config.
    withName: '.*GTF_HYBRIDMERGE_GFFCOMPARE:BEDTOOLS_INTERSECT' {
        ext.args   = '-v'
        ext.prefix = { "${meta.id}_blacklisted" }
    }

    // GAWK_CONCAT (awk/concat.awk): merges the filtered survivors into the
    // backbone, synthesising a `gene` row (with union span) for any novel
    // gene_id absent from the backbone.
    withName: '.*GTF_HYBRIDMERGE_GFFCOMPARE:GAWK_CONCAT' {
        ext.prefix = { "${meta.id}_hybrid" }
    }
}

nextflow_workflow {

    name "Test Subworkflow GTF_HYBRIDMERGE_GFFCOMPARE"
    script "../main.nf"
    config "../nextflow.config"

    workflow "GTF_HYBRIDMERGE_GFFCOMPARE"

    tag "subworkflows"
    tag "subworkflows_nfcore"
    tag "subworkflows/gtf_hybridmerge_gffcompare"

    tag "gffcompare"
    tag "gawk"
    tag "bedtools"
    tag "bedtools/intersect"

    test("chr21 reference + chr22 novel - no blacklist") {

        when {
            workflow {
                """
                input[0] = channel.of([
                    [id: 'chr22_novel'],
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/genome.gtf', checkIfExists: true)
                ])
                input[1] = channel.value([
                    [id: 'chr21_reference'],
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/chr21/sequence/chr21_gencode.gtf', checkIfExists: true)
                ])
                input[2] = channel.value([
                    [id: 'chr21_backbone'],
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/chr21/sequence/chr21_gencode.gtf', checkIfExists: true)
                ])
                input[3] = channel.value("u,j,i,k,m,n,o,p,r,s,x,y,=")
                input[4] = channel.empty()
                """
            }
        }

        then {
            def hybridLines = path(workflow.out.hybrid_gtf[0][1]).readLines().findAll { !it.startsWith('#') }
            def chr22Rows   = hybridLines.findAll { it.split('\t', -1)[0] == 'chr22' }
            def synthGenes  = chr22Rows.findAll { it.split('\t', -1)[2] == 'gene' }
            def synthSpanMatchesUnion = {
                def geneSpans = [:]
                def txStarts  = [:].withDefault { [] }
                def txEnds    = [:].withDefault { [] }
                chr22Rows.each { line ->
                    def c = line.split('\t', -1)
                    def gid = (c[8] =~ /gene_id "([^"]+)"/)[0][1]
                    if (c[2] == 'gene') geneSpans[gid] = [c[3] as int, c[4] as int]
                    if (c[2] == 'transcript') { txStarts[gid] << (c[3] as int); txEnds[gid] << (c[4] as int) }
                }
                geneSpans.every { gid, span -> span[0] == txStarts[gid].min() && span[1] == txEnds[gid].max() }
            }
            assertAll(
                { assert workflow.success },
                { assert workflow.out.hybrid_gtf.size() == 1 },
                { assert hybridLines.every { it ==~ /.*gene_id "[^"]+";.*/ },
                    "hybrid GTF has lines without a well-formed gene_id \"...\"; attribute" },
                { assert workflow.out.hybrid_gtf[0][0] == [id: 'chr21_backbone'],
                    "hybrid_gtf meta should equal the backbone meta but was ${workflow.out.hybrid_gtf[0][0]}" },
                { assert synthGenes.size() > 0,
                    "no synthesised gene rows on chr22; the concat awk did not graft any novel genes" },
                { assert synthSpanMatchesUnion(),
                    "synthesised gene row spans do not match the union of their child transcripts; concat awk has regressed on gene-span correctness" },
                { assert snapshot(
                    workflow.out.hybrid_gtf,
                    workflow.out.gffcompare_stats,
                    workflow.out.gffcompare_tracking,
                    workflow.out.gffcompare_loci
                ).match() }
            )
        }
    }

    test("chr21 reference + chr22 novel - with chr22 blacklist") {

        when {
            workflow {
                """
                input[0] = channel.of([
                    [id: 'chr22_novel'],
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/genome.gtf', checkIfExists: true)
                ])
                input[1] = channel.value([
                    [id: 'chr21_reference'],
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/chr21/sequence/chr21_gencode.gtf', checkIfExists: true)
                ])
                input[2] = channel.value([
                    [id: 'chr21_backbone'],
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/chr21/sequence/chr21_gencode.gtf', checkIfExists: true)
                ])
                input[3] = channel.value("u,j,i,k,m,n,o,p,r,s,x,y,=")
                input[4] = channel.of([
                    [id: 'chr22_blacklist'],
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/genome.blacklist_intervals.bed', checkIfExists: true)
                ])
                """
            }
        }

        then {
            def hybridLines = path(workflow.out.hybrid_gtf[0][1]).readLines().findAll { !it.startsWith('#') }
            assertAll(
                { assert workflow.success },
                { assert workflow.out.hybrid_gtf.size() == 1 },
                { assert hybridLines.every { it ==~ /.*gene_id "[^"]+";.*/ },
                    "hybrid GTF has lines without a well-formed gene_id \"...\"; attribute" },
                { assert workflow.out.hybrid_gtf[0][0] == [id: 'chr21_backbone'],
                    "hybrid_gtf meta should equal the backbone meta but was ${workflow.out.hybrid_gtf[0][0]}" },
                { assert snapshot(
                    workflow.out.hybrid_gtf,
                    workflow.out.gffcompare_stats,
                    workflow.out.gffcompare_tracking,
                    workflow.out.gffcompare_loci
                ).match() }
            )
        }
    }
}

